NAME = 'sml_BL_2008: Kitab Awal-Jaman maka Kitab Injil'
BOOK = 'Ruth'

CHAPTERS = {
    1: {
        1: "Ma waktu pa'in aniya' maghuhukum analassay palkala' ma bangsa Isra'il, bay ginotom lahat sigām. Manjari aniya' dakayu' l'lla min kauman Betlehem magbeya' maka h'ndana maka duwa anakna l'lla bay papinda ni lahat Mowab.",
        2: "Ya ōn l'lla itu si Elemelek, h'ndana si Naomi, ōn duwangan anakna inān si Mahalon maka si Kiliyon. Sigām itu tumpuk Eprat min kauman Betlehem ma lahat Yuda. Bay sigām papinda ni lahat Mowab bo' mahē' maglahat.",
        3: "Na, at'ggol-t'ggol pa'in sigām maina'an, amatay si Elemelek ya h'lla si Naomi, ati si Naomi la'a maka karuwangan anakna tabba.",
        4: "Makah'nda duwangan anakna inān ni d'nda bangsa Mowab, ya ōn sigām si Orpa maka si Rūt. Palabay pa'in sangpū' tahun,",
        5: "amatay isab disi Mahalon maka si Kiliyon, jari si Naomi la'a takapin pagka amatay na anak-h'llana.",
        6: "Masi gi' sigām ma lahat Mowab, kahaka'an si Naomi pasal saga a'a ma lahatna porol, aheka kono' pagkakan sigām ma sabab kaheya tabang PANGHŪ'.",
        7: "Manjari, ala'an na sigām min lahat bay pat'nna'an sigām inān bo' pabīng ni Yuda ya lahatna.",
        8: "Ma pal'ngnganan pa'in, ah'lling si Naomi ni saga ayuwanna inān, yukna, “Saga dayang, amole' na kam pabalik ni saga matto'abi. Mura-murahan bang pa'in kam binuwanan kahāpan e' PANGHŪ' buwat kahāpan bay tahinangbi ma aku maka saga kah'lla'anbi he'.",
        9: "Bang pa'in kam isab nirūlan e'na makapagh'lla maka kaniya'an kam kahāpan ma deyoman sigām.” Jari, siniyum e' si Naomi saga ayuwanna ati anangis to'ongan duwangan itu",
        10: "maka he' sigām ah'lling ni iya, yuk-i, “Ameya' na kami pabīng ma ka'a ni saga kampungnu.”",
        11: "Saguwā' anambung si Naomi, yukna, “Saga dayang, magpamole' na kam. Angay kam subay ameya' ma aku? Mbal na aku makabāk anak tapamah'llaku ma ka'am pabīng.",
        12: "Pehē' na kam,” yukna, “aku itu ato'a na. Mbal na aku makah'lla. Maka minsan isab aniya' h'llaku pahulid ni aku sangom ilu bo' aku maka'anak pabalik,",
        13: "makalagad bahā' kam sampay sigām ta'abut asubul? Tantu mbal na. Gom gi' ka'am ilu saga dayang, da'a na buwat aku itu sabab ahunit landu' ya bay pamat'kka e' PANGHŪ' ma aku.”",
        14: "Ma pasal pamissala si Naomi he', anangis sigām pabīng. Jari pasiyum maka ama'id na si Orpa, sagō' si Rūt paunung ma mato'ana.",
        15: "Yuk si Naomi, “O'o, nda'un ba, bilasnu ilu amole' na ni saga matto'ana maka ni pagtuhananna. Na, pehē' na ka ameya' ma iya.”",
        16: "Sagō' ya sambung si Rūt, “Da'a aku pogosun ang'bba atawa anaikutan ka'a. Pi'ingga-pi'ingga ka ameya' aku. Maingga-maingga pat'nna'annu mahē' isab aku. In bangsanu ya na bangsaku, jari in Tuhannu ya na pagtuhananku.",
        17: "Bang ka maingga amatay, mahē' du isab aku amatay maka kinubul. Bang pa'in aku minulka'an he' PANGHŪ' bang aku pa'bba min ka'a. Luwal la'a bang kamatay ya makapagbutas ma kita.”",
        18: "Tasayu pa'in e' si Naomi lilla' ameya' ma iya si Rūt, pahali na iya amogos.",
        19: "Puwas pa'in he'-i, palanjal na sigām karuwangan sampay sigām makat'kka ni Betlehem. Pag'nda' ma sigām, takuddat saga a'a ma kauman inān. Jari ah'lling saga kar'ndahan maina'an, yuk-i, “Si Naomi na bahā' ilu?”",
        20: "Sagō' yuk si Naomi ni sigām, “Da'a na aku ōninbi maka ōnku, sagō' ōninbi na aku Mara sabab bay aku pinat'kkahan e' PANGHŪ' kasukkalan mbal tapula'-pula'.",
        21: "Waktu bay kala'anku minnitu jukup-jukupan gi' aku, sagō' bay aku pinabalik he' PANGHŪ' pi'itu ma halam na aniya' ai-aiku. Angkan da'a na aku ōninbi Naomi sabab bay aku pinat'kkahan kasukkalan maka kulang-kabus he' PANGHŪ' Sangat Kawasa.”",
        22: "Jari makabalik si Naomi maka ayuwanna si Rūt min Mowab. At'kka sigām ni Betlehem ma timpu yampa anagna' pagani.",
    },
    2: {
        1: "Manjari, aniya' l'lla pinagōnan si Bowas, a'a taga-kaniya' maka ga'osan. Min tumpuk si Elemelek iya, pamikitan si Naomi min h'llana.",
        2: "Dakayu' llaw, ah'lling si Rūt ni si Naomi, yukna, “Babu', papehē'un gi' aku ni huma amuwa' kapin bay paganihan ma sai-sai ya bilahi pameya'anku.” Anambung si Naomi, yukna, “Aho', pehē' ka, dayang.”",
        3: "Jari lum'ngngan na si Rūt ni huma paturul min buli'an saga a'a maga'ani inān amuwa' kapin bay paganihan he'. In tag-dapu huma inān ya na si Bowas kampung si Elemelek.",
        4: "Ma waktu ina'an-i, at'kka si Bowas bay min Betlehem ati sinagina e'na saga a'a maga'ani he', yukna, “Owa'! Bang pa'in PANGHŪ' pabeya' ma ka'am!” Yuk isab sambung saga a'a inān, “Bang pa'in ka binarakatan e' PANGHŪ'!”",
        5: "Jari atilaw si Bowas ni kapatas saga maga'ani yukna, “Sai sa d'nda inān?”",
        6: "Anambung kapatas itu, yukna, “D'nda ilu a'a bangsa Mowab bay ameya' pi'itu ma si Naomi min lahat Mowab.",
        7: "Bay iya ama'id min aku bang kono' iya makajari paturul min buli'an saga maga'ani amuwa' kapin bay paganihan he'. Min abay subu lagi' kapaghinangna ilu. Ya du halianna ilu pasindung dai'-dai'.”",
        8: "Jari ah'lling si Bowas ni si Rūt yukna, “Arung, akale ka pahāp. Da'a na ka paliyu amuwa' ni huma saddī. Maitu na sadja ka magbeya' maka saga sosoho'anku kar'ndahan itu.",
        9: "Nda'un bang maingga paganihan saga a'aku ati pasambeya' ka ma saga kar'ndahan ilu. Bay na banda'anku saga kal'llahan maitu soho'ku ka da'a ni'inay ma sigām. Bang ka patay-bohe', pehē' pa'in ka angā' min kibut bay ni'isihan e' saga kal'llahan e'.”",
        10: "Pagka buwattē' ya bissala si Bowas, magtūy pasujud si Rūt ni tana' ati ah'lling, yukna, “Tuwan, angay aku pahalga'nu? Aku itu dakayu' sadja a'a liyu.”",
        11: "Sagō' anambung si Bowas yukna, “Bay aku kahaka'an ma pasal kahāpan bay tahinangnu ma mato'anu min bay gi' kamatay h'llanu. Bay kono' bbahannu ina'-mma'nu sampay lahatnu ati itu ka ameya' pat'nna' ma lahat halam bay kata'uwannu.",
        12: "Bang pa'in ka nilidjiki'an he' PANGHŪ' Sangat Kawasa ma bay tahinangnu ilu. Bang pa'in ka tinungbasan manglabi-labihan he' PANGHŪ' bangsa Isra'il, ya sapantun pikpik manuk pasindungannu.”",
        13: "Yuk sambung si Rūt, “Bang pa'in aku taptap makasulut pangatayannu, tuwan. Bay aluknu pangatayanku sabab kahāp sin saga bissalanu ilu minsan aku mbal makasibu' ni d'nda sosoho'annu.”",
        14: "Ta'abut pa'in waktu pagkakan, nilinganan si Rūt he' si Bowas, “Pi'itu ka,” yukna, “pasalu ka ma kami amangan tinapay bo' bahugun ni suka' binu-anggul itu.” Maina'an pa'in ma pagkakanan, nilabot si Rūt e' si Bowas maka pai sinanglag. Jari amangan iya pahāp sampay asso maka aniya' gi' takapin.",
        15: "Bay pa'in he'-i, an'ngge na iya bo' pabalik ni paghinanganna. Ah'lling si Bowas ni saga sosoho'anna yukna, “Amay-amay, da'a iya lāngunbi minsan iya amuwa' ma tongod saga p'kkosan.",
        16: "Gom pa'in ngā'inbi iya min p'kkosan he' bo' pat'nna'unbi ma pamuwa'anna. Dūlinbi sadja iya.”",
        17: "Angkan mahē' na pa'in si Rūt ma huma sampay ni kasangoman. Pagt'ppana saga buwa' pai-tirigu bay tapuwa'na he', magbuhat saga sangpū' gantang.",
        18: "Manjari binowa e'na amole' ati ta'nda' e' mato'ana bang pila heka bay tatimukna. Sinōngan isab e'na ni mato'ana ya labi min bay pamangananna he'.",
        19: "Sakali tinilaw iya e' mato'ana, yuk-i, “Maingga ka bay amuwa' llaw ilu? Sai tag-dapu huma bay paghinangannu? Bang pa'in aheya kahāpan ma a'a bay amaidda ka'a ilu.” Jari nihaka e' si Rūt ma si Naomi pasalan ya tag-dapu lugal bay paghinanganna he'. “Si Bowas,” yukna, “ya ōn a'a bay paghinanganku llaw itu.”",
        20: "“PANGHŪ' magbarakat ma si Bowas,” yuk si Naomi. “Halam pahali kahāpanna ma saga allum maka ma saga wa'i na magpatayan.” Ah'lling gi' si Naomi, yukna, “Ya l'lla ōnannu ilu kampungtam du. Ya ilu taga-kapatut anabangan kita.”",
        21: "Ah'lling gi' si Rūt, “Bay isab iya ah'lling ma aku sinoho' gi' aku ameya' ma saga sosoho'anna sampay sigām aubus magani.”",
        22: "Yuk si Naomi ni si Rūt, “Ahāp ko' he' bang ka mahē' ma humana magbeya' maka saga sosoho'anna kar'ndahan. Sabab bang a'a saddī ya pameya'annu, aniya' arai' angala'at ka'a.”",
        23: "Jari mahē' na si Rūt maka saga sosoho'an si Bowas kar'ndahan sampay aubus musim pagani. Sagō' masi iya pat'nna' ma mato'ana.",
    },
    3: {
        1: "Dakayu' llaw ah'lling si Naomi ni si Rūt, “Dayang,” yukna, “piha'anta ka pat'nna'an atotog bo' aniya' magnapaka ma ka'a.",
        2: "Kampungta asal si Bowas, ya tag-dapu huma bay paghinangan saga kar'ndahan bay pameya'annu he'. Sangom itu, pehē' iya ni tongod pagt'ppahan bo' magtahap saga bay niani he'.",
        3: "Amandi ka bo' ka amahamut di-nu. Jari sulugun badju'nu ahāp to'ongan bo' ka pehē' ni pagt'ppahan. Da'a iya pata'uhun in ka'a wa'i mahē', subay na iya aubus amangan maka anginum.",
        4: "Bang iya makalege na, gindanin bang ma atag ingga palegehanna. Jari pehē' ka, laisun mantana bo' ka abahak ma tape'anna. Nihaka'an du ka e'na bang ai subay hinangnu.”",
        5: "Anambung si Rūt yukna, “Beya'ku kamemon panoho'annu ilu, babu'.”",
        6: "Manjari bineya' he' si Rūt panoho'an mato'ana ati pehē' na iya ni tongod pagt'ppahan.",
        7: "Aubus pa'in bay amangan maka anginum si Bowas bo' hinabu ahāp palasahanna, pabahak iya ma tongod pagtau'an pai. Jari tatuli pa'in iya, pasekot pina'an si Rūt kamaya'-maya' bo' nilais manta min tape' si Bowas ati palege iya ma tape'an.",
        8: "Alalom pa'in bahangi, takuddat si Bowas angkan iya makahimuya, maka aniya' d'nda tasayuna palege ma atag tape'na.",
        9: "“Sai sa ka'a ilu?” yukna. Anambung si Rūt, “Aku itu si Rūt, ya sosoho'annu,” yukna. “Pagka ka'a ilu kampung kami taga-kapatut, b'llatun gi' tōng mantanu ma aku.”",
        10: "“Mura-murahan bang pa'in ka nilidjiki'an e' PANGHŪ', dayang,” yuk si Bowas. “Ya kahāpan tahinangnu buwattina'an aheya gi' min bay tahinangnu dahū. Halam ka bay sinōd baya' ma kal'llahan abata', ai na ka miskin atawa dayahan.",
        11: "Angkan buwattina'an, da'a na ka asusa sabab beya'ku kamemon pangamu'nu. Makata'u du isab kamemon lūng-kampungnu in ka'a ilu d'nda abontol.",
        12: "B'nnal ya yuknu ilu, in aku dakayu' kampungnu taga-kapatut anabangan ka'a, sagō' aniya' gi' kampungnu labi aga'os min aku.",
        13: "Maitu na ka atuli sangom itu. Salung subu, pehē'ku a'a he', kalu niakuhan e'na amah'nda ka'a. Bang hati' iya angaku, ahāp. Sagō' bang mbal, na saksi'ta PANGHŪ' ya allum salama-lama in aku itu angakuhan ka'a du. Maitu na ka atuli.”",
        14: "Manjari palege na si Rūt maina'an sampay ni kasubuhan. Pagdai' llaw pabangun na iya ma halam lagi' aniya' makasayuhan iya. Yuk si Bowas ma saga a'ana, “Da'a kam amata'u ni sai-na saga aniya' d'nda bay makapi'itu ni pagt'ppahan.”",
        15: "Ah'lling lagi' si Bowas, yukna, “Bowahun pi'itu se'ob ma barannu ilu bo' b'llatun maitu.” Pagb'llat pa'in se'ob inān, tin'ppongan iya nnom gantang pai-tirigu bay tin'ppa bo' pinadurung ma iya. Jari amole' na pabīng si Bowas ni kaumanna.",
        16: "Makapole' pa'in si Rūt, tinilaw iya e' mato'ana, yuk-i, “Buwattingga du, dayang?” Sinuli-sulihan e' si Rūt mato'ana bang ai bay tahinang e' si Bowas ma iya.",
        17: "Maka yukna gi' isab, “Bay aku binuwanan nnom gantang pai-tirigu e' si Bowas, sabab bang ma iya, sinoho' aku mbal amole' bang halam aniya' tabowaku pamuwan ma ka'a.”",
        18: "Manjari ah'lling si Naomi, “Angagad-ngagad na sadja ka, dayang, sampay tata'unu bang ai kataluwa'anna. Tantu mbal pahali si Bowas llaw itu bang halam aniya' kajatuhan palkala' itu.”",
    },
    4: {
        1: "Manjari itu, hinabu magsuli-suli si Naomi maka si Rūt, pehē' si Bowas aningkō' ma atag lawang ya pagsōran kauman Betlehem e'. Sakali palabay minna'an dakayu' kampung si Naomi ya bay pinagpa'in e' si Bowas. Magtūy lingananna bo' binowa magsuli-suli. Yuk si Bowas, “O tuwan, pi'itu gi' ka aningkō'.” Na pasekot a'a inān aningkō'.",
        2: "Sakali pinalinganan e' si Bowas sangpū' pagmatto'ahan ma kauman inān. Yukna ni sigām, “Aningkō' kam maitu saga tuwan.” Jari aningkō' isab sigām.",
        3: "Makatingkō' pa'in sigām kamemon, ah'lling si Bowas ni kampung he', yukna, “Tuwan, in si Naomi, ya balu si Elemelek, bay na pabīng pi'itu min lahat Mowab maka aniya' niyatna angandagangan tana' si Elemelek ya bay kampungta.",
        4: "Wajib ka pahatiku, kalu ka bilahi angal'kkat. Bang ka bilahi, atiya' saga pagmatto'ahanta anaksi', beya' isab saga a'a kasehe'an ya magtingkō'an maitu. Damikiyanna isab bang ka mbal, haka'in aku bo' kata'uwanku. Sabab halam aniya' saddī taga-kapatut angal'kkat tana' inān bang ngga'i ka ka'a bo' yampa aku.” “Aho', l'kkatku na,” yuk kampung si Bowas inān.",
        5: "Jari ah'lling si Bowas, “Pagka b'llinu na tana' min si Naomi maka ayuwanna si Rūt ya d'nda Mowab, akuhannu du isab ningā' h'nda si Rūt. Jari mbal alungay ōn si Mahalon minsan amatay, sabab kaniya'an iya anak min bay h'ndana, maka aniya' na pa'in tubu' pamusaka'an tana'na.”",
        6: "Anambung kampung inān, yukna, “Bang buwattilu hatulanna, mbal aku maka'aku angal'kkat tana' ilu sabab mbal du tahinangku pusaka'. Na, ka'a na ya angal'kkat sabab mbal tagagaku.”",
        7: "(Na ya addat ma masa he'-i ma lahat Isra'il, bang aniya' a'a magpal'kkat atawa magdagang ai-ai pangalta'na, subay niurusan taumpa'na bo' ni'nde'an ni a'a angal'kkat inān. Ya itu hatulan sara' ma bangsa Isra'il ma takdil l'ngngan kataddangan.)",
        8: "Angkan yuk kampung inān ni si Bowas, “Ka'a na am'lli tana' ilu.” Magtūy niurusan taumpa'na.",
        9: "Buwattē' pa'in, amissala si Bowas ni saga pagmatto'ahan maka saga a'a maina'an, yukna, “Kasaksi'anbi ma llaw itu aku ya makab'lli min si Naomi kamemon palsuku'an si Elemelek, si Kiliyon maka si Mahalon.",
        10: "Damikiyanna si Rūt ya d'nda bangsa Mowab, ya bay balu si Mahalon, ta'ā'ku na h'nda bo' supaya aniya' tubu' pinusaka'an kamemon bay palsuku'an a'a mamatay itu. Mbal isab takalipat ōnna min pangentom saga kaukampunganna atawa min lahatna. Saksi' kam llaw itu.”",
        11: "Anambung saga pagmatto'ahan maka saga a'a maina'an ma tongod lawang kauman e'. Yuk-i, “Aho', saksi' kami. Mura-murahan bang pa'in d'nda ya song tah'ndanu ilu binuwanan kahāpan he' PANGHŪ', pinasali' ni kahāpan bay tapamuwanna ma si Leya maka si Rakiya ya pagina'an bangsa Isra'il.” Yuk sigām gi' isab, “Bang pa'in pasōng kahaldayanu ma tumpuk Eprat maka patanyag ōnnu ma Betlehem.",
        12: "Bang pa'in aniya' tubu' pamuwan ka'a he' PANGHŪ' min d'nda itu, bo' pasali' ka'anakannu ni anak si Peres, ya anak si Yuda min si Tamar.”",
        13: "Manjari ningā' na h'nda si Rūt he' si Bowas. Makapagdakayu' pa'in sigā, ab'ttong si Rūt min kahandak PANGHŪ' ati anganak l'lla.",
        14: "Yuk saga kar'ndahan maina'an ni si Naomi, “Pudjitam PANGHŪ' sabab mbal ka kasiya-siyahan. Ma llaw itu du aniya' mpunu l'lla taga-kapatut amaruli ka'a. Bang pa'in atanyag onde' ilu ma katilingkal Isra'il.",
        15: "Iya ya amalasig ka'a maka angipat ka'a bang ka ta'abut na ato'a. Sabab ina' onde' ilu, ya na ayuwannu. Alasa iya ma ka'a, maka aheya halga'na ma ka'a min anak l'lla pitu' hekana.”",
        16: "Ati giniba he' si Naomi onde' inān ati ni'ipat he'na.",
        17: "Yuk saga kar'ndahan ma jadjahan ina'an, “Ahā, aniya' na anak si Naomi!” Jari Obed ya pangōn sigām ma iya. Na, si Obed itu ya na mma' si Jesse, si Jesse ya na mma' si Da'ud.",
        18: "Ya itu panubu' si Peres: Si Peres ya na mma' si Hesdon,",
        19: "si Hesdon ya na mma' si Rām. Si Rām ya na mma' si Aminadab,",
        20: "si Aminadab ya na mma' si Nason. Si Nason ya na mma' si Salmon,",
        21: "si Salmon ya na mma' si Bowas. Si Bowas ya na mma' si Obed,",
        22: "si Obed itu ya na mma' si Jesse, Si Jesse itu ya na mma' si Da'ud.",
    },
}
